package com.gwsheridan.worldarchitect.release;

import com.google.gson.*;
import java.nio.file.*;
import java.util.*;

/** Maintains immutable previous examples and prepares self-contained new-world projects. */
public final class ReleaseCycle18Examples {
    private static final String MANIFEST="worldarchitect.bundle.json";
    public static void main(String[] args)throws Exception{
        Path root=Path.of(args[0]);String version=args[1];if(!version.equals("1.8.0"))throw new IllegalArgumentException("Use the reviewed example release");
        for(String kind:List.of("classic","choice","teams","mixed")){
            var files=ReleaseExamples.read(root.resolve("examples/creator-starters/bundles/skyblock-1.7.0.zip"));var manifest=ReleaseExamples.json(files.get(MANIFEST));String previous=manifest.get("preset").getAsString();var preset=ReleaseExamples.json(files.remove(presetPath(previous)));String id="worldarchitect_examples:modpack_"+kind;manifest.addProperty("preset",id);manifest.addProperty("format",3);manifest.addProperty("release",version);manifest.addProperty("author","GWSHERIDAN");manifest.addProperty("title",switch(kind){case "classic"->"Classic Skyblock pack";case "choice"->"Choose your island";case "teams"->"Team island pack";default->"Mixed-dimension authoring pack";});manifest.addProperty("description",switch(kind){case "classic"->"A shared starting island with explicit chest contents and a bounded water source.";case "choice"->"Players choose a pre-generated classic or orchard island; their supplies never refill.";case "teams"->"The first team member chooses its persistent shared island.";default->"Personal Overworld islands, a shared Nether island and a native End, with editable protection defaults.";});manifest.addProperty("lock",kind.equals("mixed")?"partial":"full");manifest.remove("editable_dimensions");manifest.remove("editable_features");manifest.remove("editable_options");manifest.remove("inheritance");manifest.addProperty("allow_structure_library",false);
            var policy=new JsonObject();policy.addProperty("version",1);var defaults=new JsonObject();defaults.addProperty("version",1);var protection=new JsonObject();for(String key:List.of("breaking","placement","containers","shared"))protection.addProperty(key,true);defaults.add("protection",protection);policy.add("defaults",defaults);var editable=new JsonArray();if(kind.equals("mixed"))editable.add("protection");policy.add("editable",editable);manifest.add("pack",policy);manifest.getAsJsonObject("options").addProperty("seed",18);
            var dimensions=preset.getAsJsonObject("dimensions");var old=dimensions.getAsJsonObject("minecraft:overworld").getAsJsonObject("generator");var small=old.getAsJsonObject("island").getAsJsonObject("template");var classic=new JsonObject();classic.addProperty("format",1);classic.add("size",small.get("size").deepCopy());var markers=new JsonObject();markers.add("spawn",small.get("spawn").deepCopy());classic.add("markers",markers);classic.addProperty("spawn_marker","spawn");classic.add("blocks",small.get("blocks").deepCopy());starterContents(classic,new int[]{2,4,4});basin(classic,new int[]{6,4,6});
            var rich=new JsonObject();rich.addProperty("type","worldarchitect:skyblock");rich.addProperty("generator_version",1);rich.add("biome",old.get("biome").deepCopy());rich.add("dimension",old.get("dimension").deepCopy());var catalog=new JsonObject();catalog.addProperty("lobby","classic");catalog.addProperty("mode",kind.equals("choice")||kind.equals("teams")?"choice":"fixed");catalog.addProperty("teams",kind.equals("teams"));catalog.addProperty("origin_y",64);catalog.addProperty("spacing",128);catalog.addProperty("personal_slots",kind.equals("classic")?0:64);var types=new JsonArray();types.add(entry("classic","Classic island","A compact grass island with a sapling, starter chest and contained water.","minecraft:grass_block",classic));if(kind.equals("choice")||kind.equals("teams"))types.add(entry("orchard","Orchard island","A custom captured-style island with an oak tree and room to build.","minecraft:oak_sapling",orchard()));catalog.add("types",types);rich.add("catalog",catalog);dimensions.getAsJsonObject("minecraft:overworld").add("generator",rich);
            if(kind.equals("mixed")){var nether=rich.deepCopy();nether.addProperty("biome","minecraft:nether_wastes");var nativeNether=dimensions.getAsJsonObject("minecraft:the_nether");var profile=new JsonObject();profile.addProperty("min_y",0);profile.addProperty("height",256);nether.add("dimension",profile);nether.getAsJsonObject("catalog").addProperty("personal_slots",0);nativeNether.add("generator",nether);}
            files.put(presetPath(id),ReleaseExamples.bytes(preset));files.put(MANIFEST,ReleaseExamples.bytes(manifest));var pack=ReleaseExamples.json(files.get("pack.mcmeta"));pack.getAsJsonObject("pack").addProperty("description",manifest.get("title").getAsString()+" for World Architect "+version);files.put("pack.mcmeta",ReleaseExamples.bytes(pack));String name="modpack-"+kind;var directory=root.resolve("examples/modpack-builder");ReleaseExamples.save(files,directory.resolve("bundles/"+name+"-"+version+".zip"),directory.resolve(name+"-"+version+"-source"));
        }
        System.out.println("Prepared four new example bundles. Unchanged examples retain their existing releases.");
    }
    private static String presetPath(String id){String[] p=id.split(":",2);return "data/"+p[0]+"/worldgen/world_preset/"+p[1]+".json";}
    private static JsonArray pos(int... v){var a=new JsonArray();for(int n:v)a.add(n);return a;}
    private static void cell(JsonObject build,int[] p,String state,JsonObject data){var cell=new JsonObject();cell.add("pos",pos(p));cell.addProperty("state",state);if(data!=null)cell.add("data",data);build.getAsJsonArray("blocks").add(cell);}
    private static JsonObject entry(String id,String title,String description,String icon,JsonObject build){var entry=new JsonObject();entry.addProperty("id",id);entry.addProperty("title",title);entry.addProperty("description",description);entry.addProperty("icon",icon);entry.addProperty("weight",1);entry.add("template",build);return entry;}
    private static void starterContents(JsonObject build,int[] p){var data=new JsonObject();data.addProperty("id","minecraft:chest");var items=new JsonArray();String[] ids={"oak_sapling","ice","bread","lava_bucket"};int[] amounts={3,2,8,1};for(int i=0;i<ids.length;i++){var item=new JsonObject();item.addProperty("Slot",i);item.addProperty("id","minecraft:"+ids[i]);item.addProperty("count",amounts[i]);items.add(item);}data.add("Items",items);cell(build,p,"minecraft:chest",data);}
    private static void basin(JsonObject build,int[] p){for(int[] d:new int[][]{{-1,0},{1,0},{0,-1},{0,1}})cell(build,new int[]{p[0]+d[0],p[1],p[2]+d[1]},"minecraft:glass",null);cell(build,p,"minecraft:water[level=0]",null);}
    private static JsonObject orchard(){var build=new JsonObject();build.addProperty("format",1);build.add("size",pos(32,16,32));var markers=new JsonObject();markers.add("arrival",pos(13,4,13));build.add("markers",markers);build.addProperty("spawn_marker","arrival");build.add("blocks",new JsonArray());for(int x=11;x<=20;x++)for(int z=11;z<=20;z++)for(int y=0;y<4;y++)cell(build,new int[]{x,y,z},y==3?"minecraft:grass_block":y==0?"minecraft:stone":"minecraft:dirt",null);for(int y=4;y<=8;y++)cell(build,new int[]{15,y,15},"minecraft:oak_log[axis=y]",null);for(int x=13;x<=17;x++)for(int z=13;z<=17;z++)for(int y=7;y<=9;y++)if((x!=15||z!=15||y>8)&&!(Math.abs(x-15)==2&&Math.abs(z-15)==2))cell(build,new int[]{x,y,z},"minecraft:oak_leaves[distance=1,persistent=true,waterlogged=false]",null);starterContents(build,new int[]{13,4,15});basin(build,new int[]{18,4,18});return build;}
}
